def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            if key in cache:
                _, wt = cache[key]
                if t - wt >= ttl:
                    # expired, remove
                    del cache[key]
            if key in cache:
                # still present, update
                cache[key] = (value, t)
                cache.move_to_end(key)
            else:
